on conflict (academic_year, week_number, grade, subject) do update set
  term = excluded.term,
  start_date = excluded.start_date,
  end_date = excluded.end_date,
  start_hijri = excluded.start_hijri,
  end_hijri = excluded.end_hijri,
  grade_label = excluded.grade_label,
  domain = excluded.domain,
  skill = excluded.skill,
  skill_code = excluded.skill_code,
  learning_goal = excluded.learning_goal,
  assessment_title = excluded.assessment_title,
  question_count = excluded.question_count,
  difficulty_level = excluded.difficulty_level,
  nafs_alignment = excluded.nafs_alignment,
  source_reference = excluded.source_reference,
  status = excluded.status,
  notes = excluded.notes,
  updated_at = now();

notify pgrst, 'reload schema';
